using System;
using System.Collections.Generic;
using UnityEngine;

namespace ResolverMaster.Games.Plumber.View
{
    /// <summary>
    /// Pipe art generated by code (until the final art arrives): rounded pipes drawn with signed distance fields into white masks with a
    /// darker rim, tinted by the board (grey = empty, water color = full). Base orientation = rotation 0 of <see cref="PieceShapes"/>
    /// (texture y up = cell Up). Generated once per set of <see cref="PlumberConfig"/> shape values and kept for the whole run.
    /// </summary>
    public sealed class PipeSprites
    {
        const float RimShade = 0.64f;

        static readonly Dictionary<string, PipeSprites> s_cache = new Dictionary<string, PipeSprites>();

        readonly Dictionary<PieceKind, Sprite> _pieces = new Dictionary<PieceKind, Sprite>();
        public Sprite Tile { get; private set; }
        public Sprite Disk { get; private set; }

        public Sprite Get(PieceKind kind) => _pieces.TryGetValue(kind, out var s) ? s : null;

        public static PipeSprites For(PlumberConfig cfg)
        {
            string key = string.Join("|", cfg.spriteSize, cfg.pipeWidth, cfg.pipeOutline, cfg.tankRadius, cfg.sinkRingRadius,
                cfg.sinkRingWidth, cfg.tileMargin, cfg.tileRadius);
            if (s_cache.TryGetValue(key, out var cached) && cached.IsAlive) return cached;
            var sprites = new PipeSprites();
            sprites.Generate(cfg);
            s_cache[key] = sprites;
            return sprites;
        }

        /// <summary>False after the textures were destroyed (e.g. editor domain/scene changes): regenerate.</summary>
        bool IsAlive => Tile != null && Disk != null && _pieces.Count > 0 && AllAlive();

        bool AllAlive()
        {
            foreach (var s in _pieces.Values)
                if (s == null) return false;
            return true;
        }

        void Generate(PlumberConfig cfg)
        {
            int size = Mathf.Clamp(cfg.spriteSize, 32, 1024);
            float w = cfg.pipeWidth / 2f;
            float rim = cfg.pipeOutline;
            var c = new Vector2(0.5f, 0.5f);
            const float beyond = 0.05f;   // pipe ends run past the edge, so they are cut flat exactly at the cell border
            var up = new Vector2(0.5f, 1 + beyond);
            var down = new Vector2(0.5f, -beyond);
            var right = new Vector2(1 + beyond, 0.5f);
            var left = new Vector2(-beyond, 0.5f);

            float Straight(Vector2 p) => Mathf.Min(Seg(p, c, up), Seg(p, c, down)) - w;

            _pieces[PieceKind.Straight] = Make("pipe_straight", size, Straight, rim);
            _pieces[PieceKind.Curve] = Make("pipe_curve", size, p => Mathf.Abs((p - Vector2.one).magnitude - 0.5f) - w, rim);
            _pieces[PieceKind.Tee] = Make("pipe_tee", size, p => Mathf.Min(Straight(p), Seg(p, c, right) - w), rim);
            _pieces[PieceKind.Cross] = Make("pipe_cross", size, p => Mathf.Min(Straight(p), Mathf.Min(Seg(p, c, right), Seg(p, c, left)) - w), rim);
            // a round tank (the color symbol is drawn on it by the board) with its outlet
            _pieces[PieceKind.Source] = Make("pipe_source", size,
                p => Mathf.Min(Seg(p, c, up) - w, (p - c).magnitude - cfg.tankRadius), rim);
            float ringR = cfg.sinkRingRadius, ringHalf = cfg.sinkRingWidth / 2f;
            _pieces[PieceKind.Sink] = Make("pipe_sink", size,
                p => Mathf.Min(Seg(p, new Vector2(0.5f, 0.5f + ringR), up) - w, Mathf.Abs((p - c).magnitude - ringR) - ringHalf), rim);

            float m = cfg.tileMargin, r = cfg.tileRadius;
            Tile = Make("pipe_tile", size, p =>
            {
                float half = 0.5f - m;
                float qx = Mathf.Abs(p.x - 0.5f) - (half - r);
                float qy = Mathf.Abs(p.y - 0.5f) - (half - r);
                return new Vector2(Mathf.Max(qx, 0), Mathf.Max(qy, 0)).magnitude + Mathf.Min(Mathf.Max(qx, qy), 0) - r;
            }, 0f);
            Disk = Make("pipe_disk", size, p => (p - c).magnitude - (0.5f - 1.5f / size), 0f);
        }

        static float Seg(Vector2 p, Vector2 a, Vector2 b)
        {
            var pa = p - a;
            var ba = b - a;
            float h = Mathf.Clamp01(Vector2.Dot(pa, ba) / Vector2.Dot(ba, ba));
            return (pa - ba * h).magnitude;
        }

        /// <summary>
        /// Rasterizes a signed distance (cell fractions, negative inside): white inside, <see cref="RimShade"/> grey in the outer
        /// <paramref name="rim"/> band and where <paramref name="detail"/> is true, anti-aliased edge.
        /// </summary>
        static Sprite Make(string name, int size, Func<Vector2, float> sdf, float rim, Func<Vector2, bool> detail = null)
        {
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = name,
                wrapMode = TextureWrapMode.Clamp,
                filterMode = FilterMode.Bilinear,
                hideFlags = HideFlags.HideAndDontSave,
            };
            var px = new Color32[size * size];
            float pixel = 1f / size;
            for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                var p = new Vector2((x + 0.5f) * pixel, (y + 0.5f) * pixel);
                float d = sdf(p);
                float alpha = Mathf.Clamp01(0.5f - d / pixel);
                if (alpha <= 0f)
                {
                    px[y * size + x] = new Color32(255, 255, 255, 0);
                    continue;
                }
                float v = 1f;
                if (rim > 0f) v = Mathf.Lerp(RimShade, 1f, Mathf.Clamp01((-d - rim) / pixel + 0.5f));
                if (detail != null && detail(p)) v = RimShade;
                byte g = (byte)Mathf.RoundToInt(v * 255);
                px[y * size + x] = new Color32(g, g, g, (byte)Mathf.RoundToInt(alpha * 255));
            }
            tex.SetPixels32(px);
            tex.Apply(false, true);
            var sprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
            sprite.name = name;
            sprite.hideFlags = HideFlags.HideAndDontSave;
            return sprite;
        }
    }
}
